UPDATE customer_address SET recipient=#{input.recipient},phone=#{input.phone},province=#{input.province},city=#{input.city},
district=#{input.district},detail=#{input.detail},is_default=#{input.isDefault},version=version+1,updated_at=UTC_TIMESTAMP(3)
WHERE customer_id=CAST(#{owner} AS UNSIGNED) AND id=CAST(#{id} AS UNSIGNED) AND version=#{version}
